import { z } from "zod";
import { Role } from "../generated/prisma/enums.ts";

// Ids are generated by Prisma uuid(), so anything else is rejected before touching the database.
export const userIdParams = z.strictObject({ id: z.uuid() });

// Strict: unknown keys are rejected, and isActive must be a real boolean ("false" the string is not accepted).
export const roleBody = z.strictObject({ role: z.enum(Object.values(Role)) });
export const statusBody = z.strictObject({ isActive: z.boolean() });

// Unknown query params are ignored (cache-busters etc.); known ones are bounded.
export const listUsersQuery = z.object({
  page: z.coerce.number().int().min(1).max(100000).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(50),
});
